// --- IDE COMPONENT ---
const IDE = ({ project, onBack }) => {
    const [activeTab, setActiveTab] = useState('agent');
    const [activeFile, setActiveFile] = useState('main.fth');
    const [files, setFiles] = useState([]);
    const [fileContent, setFileContent] = useState('');
    const [terminalOutput, setTerminalOutput] = useState([]);
    const [isSidebarOpen, setSidebarOpen] = useState(false);
    const [isToolsOpen, setToolsOpen] = useState(false);
    const [isLoading, setLoading] = useState(false);
    const [agentMessages, setAgentMessages] = useState([]);
    const [showPreview, setShowPreview] = useState(false);

    useEffect(() => {
        fetchFiles();
        checkHealth();
    }, []);

    const checkHealth = async () => {
        try { await fetch(`${API_BASE}/health`); } catch (e) { console.error(e); }
    };

    const fetchFiles = async () => {
        try {
            const res = await fetch(`${API_BASE}/api/file/list`);
            if (res.ok) {
                const data = await res.json();
                setFiles(data.files || []);
            } else { throw new Error('Mock'); }
        } catch (e) {
            setFiles([{name: 'main.fth', type: 'file'}, {name: 'frontend.imba', type: 'file'}, {name: 'stilus.css', type: 'file'}]);
        }
        loadFile('main.fth', false);
    };

    const loadFile = async (filename, switchTab = true) => {
        setLoading(true);
        setActiveFile(filename);
        try {
            const res = await fetch(`${API_BASE}/api/file?name=${filename}`);
            if (res.ok) {
                const data = await res.json();
                setFileContent(data.content);
            } else { throw new Error('Mock'); }
        } catch (e) {
            setFileContent(`\ ${filename} tartalma...\n\ : hello-world S" Hello ${project?.name || 'World'}!" TYPE CR ;\n\ hello-world`);
        } finally {
            setLoading(false);
            if (switchTab) {
                setActiveTab('editor');
                setSidebarOpen(false);
            }
        }
    };

    const handleRun = async () => {
        setTerminalOutput(prev => [...prev, `> ${activeFile} futtatása...`]);
        setActiveTab('console');
        setTimeout(() => {
             setTerminalOutput(prev => [...prev, `Program lefutott sikeresen.`, `Kilépési kód: 0`]);
        }, 500);
    };

    const handleAgentChat = async (message) => {
        const newMessage = { role: 'user', content: message };
        setAgentMessages(prev => [...prev, newMessage]);
        setTimeout(() => {
            setAgentMessages(prev => [...prev, { role: 'assistant', content: "Értem. Elkezdtem a kért módosításokat a kódon..." }]);
        }, 1000);
    };

    const ToolItem = ({ icon, title, desc, color, onClick }) => (
        <div onClick={onClick} className="flex gap-4 p-3 rounded-xl active:bg-apple-surface transition-colors cursor-pointer bg-apple-surface border border-apple-border/50">
            <Icon name={icon} size={24} className={`${color} shrink-0 mt-1`} />
            <div className="flex flex-col">
                <span className="text-apple-text font-display font-medium text-base">{title}</span>
                <span className="text-apple-subtext text-sm leading-snug mt-1">{desc}</span>
            </div>
        </div>
    );

    return (
        <div className="flex flex-col h-screen w-full bg-apple-bg relative animate-fade-in">
            {/* Header */}
            <div className="h-14 bg-apple-bg/90 backdrop-blur-md flex items-center justify-between px-4 border-b border-apple-border z-20 safe-pt fixed top-0 w-full">
                <button className="text-apple-blue" onClick={() => setSidebarOpen(true)}>
                    <Icon name="menu" size={24} />
                </button>
                <div className="flex flex-col items-center">
                    <span className="text-apple-text font-display font-semibold text-sm">{project?.name || 'Projekt'}</span>
                    <span className="text-apple-subtext text-[10px]">Mentve</span>
                </div>
                <button className="text-apple-blue" onClick={() => setToolsOpen(true)}>
                    <Icon name="more-horizontal" size={24} />
                </button>
            </div>

            {/* Main Content */}
            <main className="flex-1 flex flex-col overflow-hidden relative">
                {isLoading ? <LoadingSpinner /> : (
                    <>
                        {activeTab === 'editor' && !showPreview && (
                            <div className="flex flex-1 overflow-hidden bg-apple-bg relative pt-14 pb-16">
                                <div className="w-10 bg-apple-bg flex flex-col items-end pr-2 pt-4 select-none border-r border-apple-border z-10">
                                    {fileContent.split('\n').map((_, i) => (
                                        <div key={i} className="text-xs text-apple-subtext font-mono leading-6">{i + 1}</div>
                                    ))}
                                </div>
                                <textarea
                                    className="flex-1 bg-transparent text-apple-text font-mono text-sm leading-6 p-4 outline-none resize-none whitespace-pre"
                                    value={fileContent}
                                    onChange={(e) => setFileContent(e.target.value)}
                                    spellCheck="false"
                                />
                            </div>
                        )}
                        {activeTab === 'preview' && (
                            <div className="flex flex-1 flex-col items-center justify-center bg-apple-bg text-center p-8 pt-14 pb-16">
                                <Icon name="monitor" size={48} className="text-apple-subtext mb-4" />
                                <h3 className="text-apple-text font-display font-medium text-lg mb-2">Előnézet</h3>
                                <p className="text-apple-subtext text-sm max-w-xs">Az alkalmazás fut, várakozás a kimenetre...</p>
                            </div>
                        )}
                        {activeTab === 'agent' && (
                            <div className="flex flex-1 flex-col bg-apple-bg pt-14 pb-16">
                                <div className="flex-1 overflow-y-auto p-4 space-y-4">
                                    {agentMessages.length === 0 ? (
                                        <div className="flex flex-col items-center justify-center h-full mt-20">
                                            <div className="w-16 h-16 bg-apple-surface rounded-2xl flex items-center justify-center mb-4 shadow-lg border border-apple-border">
                                                <Icon name="sparkles" className="text-apple-blue" size={32} />
                                            </div>
                                            <h2 className="text-xl font-display font-semibold text-apple-text mb-2">Szia! Miben segíthetek?</h2>
                                            <p className="text-apple-subtext text-center text-sm px-8 mb-8">Írd le mit szeretnél, és én megírom a kódot.</p>
                                            <div className="grid grid-cols-2 gap-2 w-full px-4">
                                                <button className="bg-apple-surface text-xs text-apple-text p-3 rounded-lg border border-apple-border text-left active:bg-apple-border transition">Hibakeresés</button>
                                                <button className="bg-apple-surface text-xs text-apple-text p-3 rounded-lg border border-apple-border text-left active:bg-apple-border transition">Új funkció</button>
                                            </div>
                                        </div>
                                    ) : (
                                        agentMessages.map((msg, i) => (
                                            <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                                                <div className={`max-w-[80%] p-3 rounded-2xl text-sm ${msg.role === 'user' ? 'bg-apple-blue text-white' : 'bg-apple-surface text-apple-text'}`}>
                                                    {msg.content}
                                                </div>
                                            </div>
                                        ))
                                    )}
                                </div>
                                <div className="p-4 border-t border-apple-border bg-apple-bg safe-pb">
                                    <div className="bg-apple-surface rounded-pill flex items-center px-4 py-3 border border-apple-border">
                                        <input
                                            type="text"
                                            placeholder="Ide írj..."
                                            className="bg-transparent flex-1 text-apple-text outline-none text-sm placeholder-apple-subtext"
                                            onKeyDown={(e) => {
                                                if (e.key === 'Enter') {
                                                    handleAgentChat(e.target.value);
                                                    e.target.value = '';
                                                }
                                            }}
                                        />
                                        <button className="text-apple-blue"><Icon name="arrow-up-circle" size={24} /></button>
                                    </div>
                                </div>
                            </div>
                        )}
                        {activeTab === 'console' && (
                            <div className="flex flex-1 flex-col bg-apple-bg p-4 font-mono text-sm overflow-y-auto pt-14 pb-16">
                                {terminalOutput.map((line, i) => (
                                    <div key={i} className="text-apple-text mb-1 border-b border-apple-border pb-1">{line}</div>
                                ))}
                                <div className="flex items-center text-apple-subtext mt-2">
                                    <span className="mr-2">➜</span>
                                    <div className="w-2 h-4 bg-apple-blue animate-pulse"></div>
                                </div>
                            </div>
                        )}
                    </>
                )}
            </main>

            {/* Bottom Nav */}
            <div className="fixed bottom-0 left-0 right-0 h-16 bg-apple-bg/90 backdrop-blur-md border-t border-apple-border flex items-center px-4 justify-between z-30 safe-pb">
                <button
                    onClick={handleRun}
                    className="w-10 h-10 bg-apple-blue rounded-full flex items-center justify-center text-white shadow-lg active:scale-95 transition-transform"
                >
                    <Icon name="play" size={18} fill="currentColor" />
                </button>
                <div className="h-10 bg-apple-surface rounded-full flex items-center p-1 border border-apple-border">
                    <button onClick={() => { setActiveTab('preview'); setShowPreview(true); }} className={`h-full px-5 rounded-full flex items-center justify-center transition-all ${activeTab === 'preview' ? 'bg-apple-border text-white' : 'text-apple-subtext'}`}>
                        <Icon name="monitor" size={18} />
                    </button>
                    <button onClick={() => { setActiveTab('agent'); setShowPreview(false); }} className={`h-full px-5 rounded-full flex items-center justify-center transition-all ${activeTab === 'agent' ? 'bg-apple-border text-apple-blue' : 'text-apple-subtext'}`}>
                        <Icon name="sparkles" size={18} />
                    </button>
                    <button onClick={() => { setActiveTab('console'); setShowPreview(false); }} className={`h-full px-5 rounded-full flex items-center justify-center transition-all ${activeTab === 'console' ? 'bg-apple-border text-white' : 'text-apple-subtext'}`}>
                        <Icon name="terminal-square" size={18} />
                    </button>
                </div>
                <button onClick={() => setToolsOpen(true)} className="w-10 h-10 flex items-center justify-center text-apple-blue">
                    <Icon name="layout-grid" size={22} />
                </button>
            </div>

            {/* Sidebar */}
            <div className={`fixed inset-0 z-50 transform transition-transform duration-300 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
