                    <div className="h-14 flex items-center px-4 border-b border-apple-border justify-between safe-pt bg-apple-bg/50 backdrop-blur-xl">
                        <span className="font-display font-semibold text-apple-text text-lg">Fájlok</span>
                        <button onClick={() => setSidebarOpen(false)} className="text-apple-blue"><Icon name="x" size={20} /></button>
