                                <div className="flex items-center text-apple-subtext mt-2">
                                    <span className="mr-2">➜</span>
                                    <div className="w-2 h-4 bg-apple-blue animate-pulse"></div>
                                </div>
                            </div>
                        )}
                    </>
                )}
            </main>

            {/* Bottom Nav */}
            <div className="fixed bottom-0 left-0 right-0 h-16 bg-apple-bg/90 backdrop-blur-md border-t border-apple-border flex items-center px-4 justify-between z-30 safe-pb">
                <button
                    onClick={handleRun}
                    className="w-10 h-10 bg-apple-blue rounded-full flex items-center justify-center text-white shadow-lg active:scale-95 transition-transform"
                >
                    <Icon name="play" size={18} fill="currentColor" />
                </button>
                <div className="h-10 bg-apple-surface rounded-full flex items-center p-1 border border-apple-border">
                    <button onClick={() => { setActiveTab('preview'); setShowPreview(true); }} className={`h-full px-5 rounded-full flex items-center justify-center transition-all ${activeTab === 'preview' ? 'bg-apple-border text-white' : 'text-apple-subtext'}`}>
                        <Icon name="monitor" size={18} />
                    </button>
                    <button onClick={() => { setActiveTab('agent'); setShowPreview(false); }} className={`h-full px-5 rounded-full flex items-center justify-center transition-all ${activeTab === 'agent' ? 'bg-apple-border text-apple-blue' : 'text-apple-subtext'}`}>
                        <Icon name="sparkles" size={18} />
                    </button>
                    <button onClick={() => { setActiveTab('console'); setShowPreview(false); }} className={`h-full px-5 rounded-full flex items-center justify-center transition-all ${activeTab === 'console' ? 'bg-apple-border text-white' : 'text-apple-subtext'}`}>
                        <Icon name="terminal-square" size={18} />
                    </button>
                </div>
                <button onClick={() => setToolsOpen(true)} className="w-10 h-10 flex items-center justify-center text-apple-blue">
                    <Icon name="layout-grid" size={22} />
                </button>
            </div>

            {/* Sidebar */}
            <div className={`fixed inset-0 z-50 transform transition-transform duration-300 ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
                <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setSidebarOpen(false)}></div>
                <div className="absolute top-0 bottom-0 left-0 w-3/4 max-w-xs bg-apple-surface border-r border-apple-border flex flex-col animate-slide-right">
                    <div className="h-14 flex items-center px-4 border-b border-apple-border justify-between safe-pt bg-apple-bg/50 backdrop-blur-xl">
                        <span className="font-display font-semibold text-apple-text text-lg">Fájlok</span>
                        <button onClick={() => setSidebarOpen(false)} className="text-apple-blue"><Icon name="x" size={20} /></button>
                    </div>
                    <div className="p-4">
                        <button onClick={onBack} className="w-full py-2 bg-apple-surface2 rounded-lg text-sm text-apple-red font-medium flex items-center justify-center gap-2 mb-4">
                            <Icon name="log-out" size={16} /> Kilépés a Főoldalra
                        </button>
                    </div>
                    <div className="flex-1 overflow-y-auto p-2">
                        {files.map((file, i) => (
                            <button
                                key={i}
                                onClick={() => loadFile(file.name)}
                                className={`w-full flex items-center p-3 rounded-lg mb-1 text-sm transition-colors ${activeFile === file.name ? 'bg-apple-blue text-white' : 'text-apple-subtext hover:text-apple-text hover:bg-white/5'}`}
                            >
                                <Icon name={file.name.endsWith('.fth') ? 'file-code' : 'file'} size={18} className="mr-3" />
                                <span className="font-medium">{file.name}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>

            {/* Tools Modal */}
            <div className={`fixed inset-0 z-50 flex items-end justify-center transition-opacity duration-200 ${isToolsOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
                <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setToolsOpen(false)}></div>
                <div className={`w-full h-[85vh] bg-apple-surface rounded-t-[24px] flex flex-col overflow-hidden relative transform transition-transform duration-300 ${isToolsOpen ? 'translate-y-0' : 'translate-y-full'}`}>
                    <div className="flex items-center p-4 border-b border-apple-border bg-apple-surface z-10">
                        <button onClick={() => setToolsOpen(false)} className="ml-auto text-apple-blue font-semibold text-sm">Bezárás</button>
                    </div>
                    <div className="flex-1 overflow-y-auto p-4 safe-pb bg-apple-bg">
                        <div className="space-y-4">
                             <ToolItem icon="sparkles" title="Ügynök" desc="Módosítás és javítás." color="text-apple-blue" onClick={() => { setActiveTab('agent'); setToolsOpen(false); }} />
                             <ToolItem icon="terminal" title="Konzol" desc="Kimenet megtekintése." color="text-gray-400" onClick={() => { setActiveTab('console'); setToolsOpen(false); }} />
                             <div className="h-px bg-apple-border my-2"></div>
                             <ToolItem icon="git-branch" title="Git" desc="Verziókezelés." color="text-purple-400" />
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

// --- MAIN APP WRAPPER ---
const App = () => {
    const [view, setView] = useState('dashboard'); // 'dashboard' | 'ide'
    const [activeProject, setActiveProject] = useState(null);

    const handleOpenProject = (project) => {
        setActiveProject(project);
        setView('ide');
    };

    const handleBackToDashboard = () => {
        setActiveProject(null);
        setView('dashboard');
    };

    return (
        <>
            {view === 'dashboard' && <Dashboard onOpenProject={handleOpenProject} />}
            {view === 'ide' && <IDE project={activeProject} onBack={handleBackToDashboard} />}
        </>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
</script>
</body>
</html>
